{
  "items": [
    {
      "name": "Finsupp.sum",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "definition",
      "type": "{α : Type u_1} → {M : Type u_8} → {N : Type u_10} → [inst : Zero M] → [AddCommMonoid N] → (α →₀ M) → (α → M → N) → N"
    },
    {
      "name": "Finsupp.sum_nsmul",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {N : Type u_10} [inst : AddCommMonoid N] [inst_1 : Fintype α] (f : α →₀ ℕ) (g : α → N),\n  (f.sum fun a b => b • g a) = ∑ a, f a • g a"
    },
    {
      "name": "Finsupp.univ_sum_single_apply",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} [inst : AddCommMonoid M] [inst_1 : Fintype α] (i : α) (m : M),\n  ∑ j, (Finsupp.single i m) j = m"
    },
    {
      "name": "Finsupp.univ_sum_single",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} [inst : Fintype α] [inst_1 : AddCommMonoid M] (f : α →₀ M),\n  ∑ a, Finsupp.single a (f a) = f"
    },
    {
      "name": "Finsupp.sum_single",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} [inst : AddCommMonoid M] (f : α →₀ M), f.sum Finsupp.single = f"
    },
    {
      "name": "Finsupp.multinomial_eq",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f : α →₀ ℕ), f.multinomial = Nat.multinomial f.support ⇑f"
    }
  ]
}
